import { amount, button, esc, icon, jsonView, metricValue, num, safeLink, unitName } from './components.js';
import { metricComparison } from './metric-comparison.js';
const money = new Set(['revenue', 'cost', 'net_profit', 'cash_flow', 'assets', 'liabilities']);
function value(id, v, unit = 'yuan') { return money.has(id) ? (typeof v === 'number' ? amount(v, unit) + ' ' + unitName(unit) : ['assets', 'liabilities'].includes(id) ? '未提供' : '—') : metricValue(id, v); }
export function assistantView(query, result) {
    const facts = (result.facts ?? []).map((f) => `<article class="assistant-fact"><div class="assistant-fact-head"><span>${esc(f.label)}</span><strong>${f.display_value ? esc(f.display_value) : value(f.id, f.value, f.display_amount_unit)}</strong></div><small>${esc(f.period)} · 修订 ${esc(f.dataset_version)} · ${f.value == null ? '输入或基期不足' : '按已保存输入计算'}</small>${metricComparison(f)}<details><summary>查看计算依据与季度追踪</summary><p class="micro">${esc(f.formula ?? '原始录入值')}</p><ul class="trace-list">${(f.inputs ?? []).map((x) => `<li><code>${esc(x.path)}</code><span>${f.input_display_values?.[x.path] ? esc(f.input_display_values[x.path]) : f.source_display_value ? esc(f.source_display_value) : num(x.value)}</span></li>`).join('')}</ul><div class="trend-list">${(f.trend ?? []).map((x) => `<span><small>${esc(x.period)}</small><strong>${x.display_value ? esc(x.display_value) : value(f.id, x.value, f.display_amount_unit)}</strong></span>`).join('')}</div><p class="micro">数据摘要 ${esc(String(f.input_hash ?? '').slice(0, 16))} · ${esc(f.verification ?? '未核验')} ${f.source_url ? safeLink(f.source_url, '原始来源') : ''}</p></details></article>`).join('');
    const quality = (result.quality ?? []).length ? `<section class="assistant-section"><h3>输入核查 <small>${result.quality_total ?? result.quality.length} 项</small></h3>${result.quality.map((x) => `<p class="assistant-check">${esc(x.period)} · ${esc(x.message)}</p>`).join('')}</section>` : '';
    const evidence = (result.evidence_matches ?? []).length ? `<section class="assistant-section"><h3>资料候选</h3><p class="micro">检索匹配并不验证资料真实性，也不证明因果关系。</p>${result.evidence_matches.map((x) => `<details class="assistant-evidence"><summary>${esc(x.title)}</summary><p>${esc(x.excerpt)}</p><small>${esc(x.review_state)} · ${esc(x.stance)} · 摘要 ${esc(String(x.content_hash).slice(0, 12))}</small><div>${x.source_url ? safeLink(x.source_url, '打开来源') : ''}</div></details>`).join('')}</section>` : '';
    const insights = (result.insights ?? []).length ? `<section class="assistant-section"><h3>待核查问题</h3>${result.insights.map((x) => `<details><summary>${esc(x.title)}</summary><p>${esc(x.message)}</p>${jsonView(x.proof)}</details>`).join('')}</section>` : '';
    const scope = result.scope ? `<p class="assistant-scope-note">${esc(result.scope.company)}${result.scope.period ? ' · ' + esc(result.scope.period) : ''} · 数据修订 ${esc(result.scope.dataset_version)} · 输入未经独立核验</p>` : '';
    const followups = (result.followups ?? []).map((q) => button(esc(q) + icon('arrow'), 'assistant-query', 'question', `data-query="${esc(q)}"`)).join('');
    const actions = (result.actions ?? []).map((a) => button(esc(a.label) + icon('arrow'), 'assistant-route', 'question', `data-route="${esc(a.route)}" data-query="${esc(a.query ?? query)}" data-dataset-id="${esc(a.dataset_id ?? result.scope?.dataset_id ?? '')}"`)).join('');
    return `<p class="assistant-user">${esc(query)}</p><div class="assistant-reply" role="status"><p>${esc(result.answer)}</p>${scope}${facts}${quality}${evidence}${insights}<section class="assistant-section"><h3>下一步</h3><div class="assistant-questions">${actions}${followups}</div></section><small class="micro">本次为本地只读核查；外部模型调用 ${result.external_calls ?? 0} 次。</small></div>`;
}
